import html,json
from pathlib import Path
root=Path(__file__).resolve().parents[1];out=root/'outputs/featured-beauties';data=json.loads((out/'roster.json').read_text());cards=[];e=html.escape
for i,p in enumerate(data['people'],1):
 record=out/(p['key']+'.json')
 if record.exists():p.update(json.loads(record.read_text()))
 ready=(root/p['portraitAsset']).is_file();p['status']='ready' if ready else 'pending'
 src='../../'+p['portraitAsset']
 image=f'<a class="art" href="{src}" target="_blank"><img src="{src}" loading="lazy" alt="{e(p["name"])}专属全身立绘"></a>' if ready else '<div class="art pending">立绘制作中</div>'
 cards.append(f'<article data-search="{e(p["name"]+p["era"]+p["kind"])}">{image}<div class="copy"><small>{i:02} · {e(p["kind"])}</small><h2>{e(p["name"])}</h2><p>{e(p["era"])}</p><p class="skill">{e(p["specialty"])} · {"立绘已就绪" if ready else "待绘制"}</p><details><summary>造型说明</summary><p>{e(p["prompt"].split('Specific facial features')[0])}</p><p>具体容貌、配色和饰物为艺术补全。部分短舞裙、夏装剪裁和旗袍为明确的游戏化改编，不作为史实服装复原。原始编码按提供表格照录，未据编码改写姓名。</p></details></div></article>')
count=sum(p['status']=='ready' for p in data['people']);data['ready']=count;data['hiddenRoster']='其余名单与素材保留，当前版本不参与寻访及显示。'
(out/'roster.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>三十美人绘卷</title><style>*{box-sizing:border-box}body{margin:auto;max-width:1600px;padding:38px 28px;background:#f4eee2;color:#3e3228;font:15px system-ui,-apple-system,"PingFang SC",sans-serif}header{border-bottom:1px solid #c9b696;padding-bottom:24px}.kicker{letter-spacing:5px;color:#966b3d;font-size:13px}h1{font:42px serif;margin:14px 0}header p{max-width:1000px;line-height:1.9;color:#77624f}.count{display:inline-block;background:#e7dbc6;padding:10px 18px;border-radius:7px;color:#754c29}input{width:100%;padding:14px 16px;border:1px solid #c9b696;border-radius:7px;background:#fffaf1;font-size:16px;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(285px,1fr));gap:20px}article{border:1px solid #d7c8ad;border-radius:13px;overflow:hidden;background:#fffcf5}.art{height:540px;display:flex;align-items:center;justify-content:center;background:#eae1ce;background-image:radial-gradient(ellipse at 50% 40%,#fbf7ed,#e6dcc7)}.art img{display:block;width:100%;height:100%;object-fit:contain}.copy{padding:20px}small{font-size:12px;color:#957956}h2{font:28px serif;margin:8px 0}p{line-height:1.8}.copy p{margin:7px 0}.skill{color:#92734f;font-size:13px}details{font-size:12px;line-height:1.8;color:#7d6d59}details p{word-break:break-word}summary{cursor:pointer}.pending{color:#9b835f}footer{margin:30px 0;font-size:13px;color:#806b53}a{color:#85532d}[hidden]{display:none!important}@media(max-width:650px){body{padding:22px 14px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.art{height:330px}.copy{padding:12px}h2{font-size:23px}}@media print{input,details{display:none}.grid{grid-template-columns:repeat(3,1fr)}article{break-inside:avoid}.art{height:420px}}</style><header><div class="kicker">皇帝 · 人物绘卷</div><h1>三十美人</h1><p>本期只开放你指定的三十位人物，其余名单保留并隐藏。每位人物采用独立完整立绘，分别设计脸型、五官、体态和神情，结合时代、身份与文学特征制作华服、轻装和舞裙。历史、传说、文学与原作人物分别标注。</p><span class="count">COUNT / 30 位立绘就绪</span></header><input id="q" aria-label="查找美人" placeholder="按姓名、时代或人物来源查找…"><main class="grid">CARDS</main><footer>妲已按通行写法作妲己；虞美人对应虞姬；江采萍另写江采苹。谭文婉、韩翠苹保留原作姓名，具体文献身份待核。文学人物采用成年形象。<br>画面由内置 imagegen 逐人生成；历史背景启发的游戏美术，轻装与舞裙包含艺术改编。谭文婉的旗袍为架空时装版本，未宣称其历史身份或时代。<a href="../featured-beauties/roster.json">查看人物与生成记录</a></footer><script>document.querySelector('#q').addEventListener('input',e=>document.querySelectorAll('article').forEach(a=>a.hidden=!a.dataset.search.includes(e.target.value.trim())))</script></html>'''.replace('COUNT',str(count)).replace('CARDS',''.join(cards))
(out/'index.html').write_text(page)
(root/'outputs/harem-roster-draft/roster.html').write_text(page)
print(f'Featured portraits: {count}/30; original roster preview now shows only these thirty')
